static lstr L5181 = {-1, 2312, "// std/bytes. A bytes value is an lstr whose data need not be UTF-8, so a\012// string converts to bytes by sharing its buffer.\012\012static lstr* narra_bytes_from_string(lstr* s) {\012  lstr_retain(s);\012  return s;\012}\012\012// The offset of the first byte where p[0..n) stops being valid UTF-8, or -1.\012// Overlong forms, surrogates and values above U+10FFFF are invalid.\012static int64_t narra_bytes_utf8_error(const unsigned char* p, int64_t n) {\012  int64_t i = 0;\012  while (i < n) {\012    unsigned char c = p[i];\012    int64_t k;\012    uint32_t cp;\012    if (c < 0x80) { i++; continue; }\012    if (c >= 0xC2 && c <= 0xDF) { k = 1; cp = c & 0x1F; }\012    else if (c >= 0xE0 && c <= 0xEF) { k = 2; cp = c & 0x0F; }\012    else if (c >= 0xF0 && c <= 0xF4) { k = 3; cp = c & 0x07; }\012    else return i;\012    if (i + k >= n) return i;\012    for (int64_t j = 1; j <= k; j++) {\012      if ((p[i + j] & 0xC0) != 0x80) return i;\012      cp = (cp << 6) | (p[i + j] & 0x3F);\012    }\012    if (k == 2 && (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF))) return i;\012    if (k == 3 && (cp < 0x10000 || cp > 0x10FFFF)) return i;\012    i += k + 1;\012  }\012  return -1;\012}\012\012// Valid UTF-8 shares the buffer as a string; otherwise *err names the offset.\012static bool narra_bytes_to_string(lstr* b, lstr** out, lstr** err) {\012  int64_t bad = narra_bytes_utf8_error((const unsigned char*)b->data, b->len);\012  if (bad >= 0) {\012    char buf[64];\012    snprintf(buf, sizeof buf, \"invalid UTF-8 at byte %\" PRId64, bad);\012    *err = lstr_from_cstr(buf);\012    return false;\012  }\012  lstr_retain(b);\012  *out = b;\012  return true;\012}\012\012static int64_t narra_bytes_length(lstr* b) { return b->len; }\012\012static uint8_t narra_bytes_at(lstr* b, int64_t index, const char* where) {\012  if (index < 0 || index >= b->len) narra_panic(where, \"Bytes.at index out of range\");\012  return (uint8_t)b->data[index];\012}\012\012// Copies bytes start up to but not including end.\012static lstr* narra_bytes_slice(lstr* b, int64_t start, int64_t end, const char* where) {\012  if (start < 0 || end < start || end > b->len) narra_panic(where, \"Bytes.slice range out of bounds\");\012  lstr* s = lstr_new(end - start);\012  memcpy(s->data, b->data + start, (size_t)(end - start));\012  return s;\012}\012\012static lstr* narra_bytes_from_raw(const uint8_t* data, int64_t len) {\012  lstr* s = lstr_new(len);\012  if (len > 0) memcpy(s->data, data, (size_t)len);\012  return s;\012}\012"};
