static lstr L5520 = {-1, 4788, "\012// Test runner\012#include <sys/types.h>\012#include <sys/wait.h>\012#include <time.h>\012#include <errno.h>\012#include <signal.h>\012\012typedef struct narra_test_case {\012  const char* name;\012  void (*fn)(void);\012} narra_test_case;\012\012static int64_t narra_test_now_ms(void) {\012  struct timespec ts;\012  clock_gettime(CLOCK_MONOTONIC, &ts);\012  return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;\012}\012\012// The time limit of one test: NARRA_TEST_TIMEOUT seconds, default 10.\012static unsigned narra_test_limit(void) {\012  const char* s = getenv(\"NARRA_TEST_TIMEOUT\");\012  if (s && *s) {\012    char* end;\012    long v = strtol(s, &end, 10);\012    if (*end == 0 && v > 0 && v < 100000) return (unsigned)v;\012  }\012  return 10;\012}\012\012// narra_test_child runs one test in the child process.\012static void narra_test_child(const narra_test_case* c, int wfd) {\012  narra_panic_fd = wfd;\012  narra_panic_pos = 1;\012  // Line buffering keeps the output of a test that crashes.\012  setvbuf(stdout, NULL, _IOLBF, 0);\012  alarm(narra_test_limit());\012  c->fn();\012  narra_consts_release();\012  // A test-only hook, so the leak report can be tested.\012  if (getenv(\"NARRA_TEST_FORCE_LEAK\")) narra_live++;\012  if (getenv(\"NARRA_CHECK_LEAKS\") && narra_live != 0) {\012    char buf[64];\012    snprintf(buf, sizeof buf, \"leaked %lld allocations\", (long long)narra_live);\012    narra_panic(\"leak check\", buf);\012  }\012  fflush(stdout);\012  _exit(0);\012}\012\012// narra_test_arg returns the option name of an argument (\"--time\" and\012// \"-time\" both give \"time\"), or NULL for an argument that is not an option.\012static const char* narra_test_opt(const char* a) {\012  if (a[0] != '-') return NULL;\012  return a[1] == '-' \077 a + 2 : a + 1;\012}\012\012// narra_test_run returns the exit code of the run.\012static int narra_test_run(const narra_test_case* cases, int argc, char** argv) {\012  const char* filter = NULL;\012  int timing = 0;\012  for (int i = 1; i < argc; i++) {\012    const char* o = narra_test_opt(argv[i]);\012    const char* eq = o \077 strchr(o, '=') : NULL;\012    size_t n = o \077 (eq \077 (size_t)(eq - o) : strlen(o)) : 0;\012    if (o && n == 4 && strncmp(o, \"time\", 4) == 0 && !eq) {\012      timing = 1;\012    } else if (o && ((n == 6 && strncmp(o, \"filter\", 6) == 0) || (n == 10 && strncmp(o, \"golden-dir\", 10) == 0))) {\012      const char* v = eq \077 eq + 1 : (i + 1 < argc \077 argv[++i] : NULL);\012      if (!v) {\012        fprintf(stderr, \"%s needs a value\\n\", argv[i]);\012        return 2;\012      }\012      if (n == 6) filter = v; else narra_golden_dir = v;\012    } else {\012      fprintf(stderr, \"unknown argument %s; options: --filter <text>, --time, --golden-dir <dir>\\n\", argv[i]);\012      return 2;\012    }\012  }\012  int passed = 0, failed = 0;\012  unsigned limit = narra_test_limit();\012  for (const narra_test_case* c = cases; c->name; c++) {\012    if (filter && !strstr(c->name, filter)) continue;\012    int fds[2];\012    fflush(stdout);\012    fflush(stderr);\012    if (pipe(fds) != 0) { fprintf(stderr, \"cannot create a pipe\\n\"); return 1; }\012    int64_t start = narra_test_now_ms();\012    pid_t pid = fork();\012    if (pid < 0) { fprintf(stderr, \"cannot fork\\n\"); return 1; }\012    if (pid == 0) {\012      close(fds[0]);\012      narra_test_child(c, fds[1]);\012    }\012    close(fds[1]);\012    size_t cap = 256, len = 0;\012    char* msg = malloc(cap);\012    for (;;) {\012      if (len + 1 == cap) { cap *= 2; msg = realloc(msg, cap); }\012      ssize_t n = read(fds[0], msg + len, cap - 1 - len);\012      if (n < 0 && errno == EINTR) continue;\012      if (n <= 0) break;\012      len += (size_t)n;\012    }\012    msg[len] = 0;\012    close(fds[0]);\012    int status = 0;\012    while (waitpid(pid, &status, 0) < 0 && errno == EINTR) {}\012    int64_t ms = narra_test_now_ms() - start;\012    char tbuf[48] = \"\";\012    if (timing) snprintf(tbuf, sizeof tbuf, \" (%lld ms)\", (long long)ms);\012    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {\012      printf(\"ok - %s%s\\n\", c->name, tbuf);\012      passed++;\012    } else if (WIFEXITED(status) && WEXITSTATUS(status) == 101) {\012      char* nl = strchr(msg, '\\n');\012      const char* where = \"\";\012      const char* text = msg;\012      if (nl) { *nl = 0; where = msg; text = nl + 1; }\012      printf(\"FAIL - %s: %s (%s)%s\\n\", c->name, text, where, tbuf);\012      failed++;\012    } else if (WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) {\012      printf(\"FAIL - %s: timed out after %u s%s\\n\", c->name, limit, tbuf);\012      failed++;\012    } else if (WIFSIGNALED(status)) {\012      printf(\"FAIL - %s: killed by signal %d (%s)%s\\n\", c->name, WTERMSIG(status), strsignal(WTERMSIG(status)), tbuf);\012      failed++;\012    } else {\012      printf(\"FAIL - %s: exited with code %d%s\\n\", c->name, WEXITSTATUS(status), tbuf);\012      failed++;\012    }\012    free(msg);\012  }\012  if (filter && passed + failed == 0) {\012    printf(\"no tests match \\\"%s\\\"\\n\", filter);\012    fflush(stdout);\012    return 1;\012  }\012  printf(\"%d passed, %d failed\\n\", passed, failed);\012  fflush(stdout);\012  return failed \077 1 : 0;\012}\012"};
